// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        BankLegit bank = new BankLegit();

        CallerAsBank caller = new CallerAsBank(c);

        vm.deal(actor, 1 ether);

        assertEq(c.tokenBalance(actor), 0);

        vm.prank(actor);
        caller.callAirDrop();

        assertTrue(c.tokenBalance(address(caller)) == 20);
    }
}

contract CallerAsBank {
    ModifierEntrancy public c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop() external {
        c.airDrop();
    }
}

contract BankLegit {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
